import logging
import subprocess

from ta_ue_plugin_android.uepc.ue_manager_exceptions import CmdExecuteException
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra
from ta_ue_plugin_android.uepc.utils import OsCommands


class IAdbCmdRunner(object):
    """Interface used for running adb commands on UEs"""

    def __init__(self):
        """Basic initialization."""
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'ADB'})

    def adb_read_adb_output(self, ue_sn, cmd_params):
        """
        :param ue_sn: string
        :param cmd_params: string or List(string)
        :return: (string, string) - (output, error) from running cmd
        """
        raise NotImplementedError("Abstract method invoked")


class AdbCmdRunner(IAdbCmdRunner):
    """Concrete implementation of IAdbCmdRunner"""

    def __init__(self, adb_filepath='adb'):
        """
        Basic initialization.
        :param adb_filepath:
        """
        super(AdbCmdRunner, self).__init__()
        self.adb_filepath = adb_filepath

    def adb_read_adb_output(self, ue_sn, cmd_params, wait_for=True):  # pylint: disable=arguments-differ
        """
        :param ue_sn: string
        :param cmd_params: string or List(string)
        :param wait_for: bool, wait or not for the subprocess results
        :return: (string, string) - (output, error) from running cmd
        """
        if not isinstance(cmd_params, list):
            cmd_params = cmd_params.split(' ')
        args = [self.adb_filepath]
        if ue_sn:
            args += ['-s', ue_sn]
        args += cmd_params
        log_msg = "Run adb cmd: %s" % ' '.join(args)
        self.logger.debug(log_msg, extra={'ue_id': ue_sn})
        kwargs = {
            'stdout': subprocess.PIPE,
            'stderr': subprocess.PIPE,
            'bufsize': 1,
            'universal_newlines': True,
        }
        python_ver = OsCommands().get_python_version()
        if python_ver.major == 3 and python_ver.minor >= 7:
            kwargs['encoding'] = "utf-8"
        p = subprocess.Popen(args, **kwargs)
        return self._return_adb_output_and_err(wait_for, p, ue_sn)

    def _return_adb_output_and_err(self, wait_for, p, ue_sn):
        if wait_for:
            out, err = p.communicate()
            if err:
                self.logger.debug("Error when sending adb command: {}".format(err))
                self.logger.error(err, extra={'ue_id': ue_sn})
                if "command not found" in err:
                    raise CmdExecuteException("ADB command not found.\n"
                                              "Please check if adb directory is set in PATH system environment variable")
                if "device offline" in err:
                    raise CmdExecuteException("Device is offline: {}. \n"
                                              "Please reconnect your UE with USB cable or disable / enable USB hub in device manager".format(ue_sn))
            return out, err
        return None


__public_adb_cmd_runner = AdbCmdRunner()


def get_public_adb_cmd_runner():
    """
    Get public adb command runner.

    :return:
    """
    return __public_adb_cmd_runner
